     import { type PausePayload } from 'spec-pipeline/protocol';
     import { type ResolutionIr, type GoalsDoc, type GoalEntry, type NonGoalEntry } from '../../../shared/ir/resolution.js';
     import { type Screen } from '../ui/screen.js';
     export interface ResolveConfirmInput {
       readonly resolution: ResolutionIr;
       readonly goals: GoalsDoc;
       readonly cuts: readonly string[];
       readonly diffLines: readonly string[] | undefined;
       readonly record: PausePayload;
     }
     export type ResolveResult =
       | { readonly kind: 'accept'; readonly goals: readonly GoalEntry[]; readonly nonGoals: readonly NonGoalEntry[] }
       | { readonly kind: 'correction' }
       | { readonly kind: 'quit' };
     export const resolveConfirmScreen = (input: ResolveConfirmInput): Screen<ResolveState, ResolveResult>;
   The main content (C11 order, verbatim): 1 `shape: <resolution.shape>` · 2 mapping rows
   (kind 'unknown' first, then the rest in order) each `<noun>: <kind>` + ` <path>` when path
   is not null · 3 drift rows (status 'unclear' first, then the rest in order) each `<id>: <status>`
   · 4 `blast: <blastRadius joined by ', '>` · 5 each goal in state.goals `<id>: <text>` then each non-goal in state.nonGoals `<id>: <text>` · 6 each cut `cut: <text>` · 7 each diffLines line verbatim. Then the main
   prompt `a to accept, g to edit goals, c to correct, q to quit`. Main keys: `a` → accept
   (D3) · `g` → start the g walk (D3) · `c` → correction · `q` → quit · any other line → the
   main content again. The main content's goals (item 5) are state.goals (not input.goals.goals):
   after a `w` the edited list is printed. The state is `{ phase: 'main' | 'walk' | 'replace-wait' | 'walk-summary',
   index: number, goals: readonly GoalEntry[], nonGoals: readonly NonGoalEntry[],
   walkedGoals: readonly GoalEntry[], walkedNonGoals: readonly NonGoalEntry[] }` (initial: phase 'main', index 0, goals
   = input.goals.goals, nonGoals = input.goals.nonGoals, walkedGoals = [], walkedNonGoals = []).
D3 src/screens/resolve-confirm.ts: the g walk (in resolveConfirmScreen). The walk iterates
   the current list (state.goals then state.nonGoals); index ranges 0 to total-1. For an entry at index: a goal when index < state.goals.length (state.goals[index]), else a non-goal (state.nonGoals[index - state.goals.length]). The prompt is
   `<entry.id>: <entry.text> (Enter keep, r replace, d drop)`. `next` for phase 'walk':
   Enter (empty line) → keep the entry (append to walkedGoals/walkedNonGoals), index+1. `r` → phase
   'replace-wait', prompt `new text:`. `d` → drop (index+1). Any other line → re-prompt.
   When index >= total → phase 'walk-summary', prompt `goals updated (w to keep, q to abort)`.
   `next` for phase 'replace-wait': an empty or blank line re-prompts (new text:); otherwise the line
   is the new text; append the entry with that text and source RESOLVE_CONFIRM_SOURCE, index+1, phase 'walk'.
   `next` for phase 'walk-summary': `w` with walkedGoals = [] → print `keep at least one goal (q to abort)` and stay;
   `w` otherwise → state.goals = walkedGoals, state.nonGoals = walkedNonGoals, phase 'main' (the edited list becomes
   the main's list) · `q` → phase 'main' (abort; state.goals/nonGoals unchanged, walkedGoals/walkedNonGoals = []) · any other line → re-prompt.
