const entriesOf = (state: ResolveState): readonly { id: string; text: string }[] => [...state.goals, ...state.nonGoals];

const walkTurn = (state: ResolveState): Turn => {
  const next = entriesOf(state)[state.index];
  return next === undefined
    ? { state: { ...state, phase: 'walk-summary' }, out: [SUMMARY_PROMPT] }
    : { state: { ...state, phase: 'walk' }, out: [walkPrompt(next)] };
};

const advance = (state: ResolveState, goal: GoalEntryStub | undefined, nonGoal: NonGoalEntryStub | undefined): Turn => {
  const walkedGoals = goal === undefined ? state.walkedGoals : [...state.walkedGoals, goal];
  const walkedNonGoals = nonGoal === undefined ? state.walkedNonGoals : [...state.walkedNonGoals, nonGoal];
  return walkTurn({ ...state, index: state.index + 1, walkedGoals, walkedNonGoals });
};

const mainNext = (input: ResolveConfirmInput, state: ResolveState, line: string): Turn => {
  if (line === 'g') return walkTurn({ ...state, index: 0, walkedGoals: [], walkedNonGoals: [] });
  if (line === 'a') return { state, out: [], result: { kind: 'accept', goals: state.goals, nonGoals: state.nonGoals } };
  if (line === 'c') return { state, out: [], result: { kind: 'correction' } };
  if (line === 'q') return { state, out: [], result: { kind: 'quit' } };
  return toMain(input, state);
};

const walkNext = (state: ResolveState, line: string): Turn => {
  const entry = entriesOf(state)[state.index];
  const isGoal = state.index < state.goals.length;
  if (line === 'd') return advance(state, undefined, undefined);
  if (line === '') {
    const kept: GoalEntryStub | NonGoalEntryStub = isGoal ? (entry as GoalEntryStub) : (entry as NonGoalEntryStub);
    return advance(state, isGoal ? (entry as GoalEntryStub) : undefined, isGoal ? undefined : (entry as NonGoalEntryStub));
  }
  if (line === 'r') return { state: { ...state, phase: 'replace-wait' }, out: [TEXT_PROMPT] };
  return walkTurn(state);
};

const textNext = (state: ResolveState, line: string): Turn => {
  const entry = entriesOf(state)[state.index];
  const text = line.trim();
  if (text === '') return { state, out: [TEXT_PROMPT] };
  const isGoal = state.index < state.goals.length;
  const replaced: GoalEntryStub | NonGoalEntryStub = { id: entry.id, text, source: RESOLVE_CONFIRM_SOURCE };
  return advance(state, isGoal ? (replaced as GoalEntryStub) : undefined, isGoal ? undefined : (replaced as NonGoalEntryStub));
};

const summaryNext = (input: ResolveConfirmInput, state: ResolveState, line: string): Turn => {
  if (line === 'q') return toMain(input, state);
  if (line !== 'w') return { state, out: [SUMMARY_PROMPT] };
  const edited = { goals: state.walkedGoals, nonGoals: state.walkedNonGoals };
  if (edited.goals.length === 0) return { state, out: [NO_GOAL] };
  return toMain(input, { ...state, goals: edited.goals, nonGoals: edited.nonGoals });
