};

const mainNext = (input: ResolveConfirmInput, state: ResolveState, line: string): Turn => {
  if (line === 'g') return walkTurn({ ...state, index: 0, walkedGoals: [], walkedNonGoals: [] });
  if (line === 'a') return { state, out: [], result: { kind: 'accept', writes: state.writes } };
  if (line === 'c') return { state, out: [], result: { kind: 'correction' } };
  if (line === 'q') return { state, out: [], result: { kind: 'quit' } };
  return toMain(input, state);
};

const walkNext = (state: ResolveState, line: string): Turn => {
  const entry = entriesOf(state)[state.index];
  const isGoal = state.index < state.goals.length;
  if (line === 'd') return advance(state, undefined, undefined);
  if (line === '') return advance(state, isGoal ? (entry as GoalEntryStub) : undefined, isGoal ? undefined : (entry as NonGoalEntryStub));
  if (line === 'r') return { state: { ...state, phase: 'replace-wait' }, out: [TEXT_PROMPT] };
  return walkTurn(state);
};

const textNext = (state: ResolveState, line: string): Turn => {
  const entry = entriesOf(state)[state.index];
  const text = line.trim();
  if (text === '') return { state, out: [TEXT_PROMPT] };
  const isGoal = state.index < state.goals.length;
  const replaced: GoalEntryStub | NonGoalEntryStub = { id: entry.id, text, source: RESOLVE_CONFIRM_SOURCE };
  return advance(state, isGoal ? (replaced as GoalEntryStub) : undefined, isGoal ? undefined : (replaced as NonGoalEntryStub));
};

