export const resolveConfirmScreen = (input: ResolveConfirmInput): Screen<ResolveState, ResolveResult> => ({
  start: {
    state: { phase: 'main', index: 0, goals: input.goals.goals, nonGoals: input.goals.nonGoals, walkedGoals: [], walkedNonGoals: [], writes: [] },
    out: mainLines(input, { phase: 'main', index: 0, goals: input.goals.goals, nonGoals: input.goals.nonGoals, walkedGoals: [], walkedNonGoals: [], writes: [] }),
  },
  next: (state, line) => {
    const phases: Readonly<Record<Phase, () => Turn>> = {
