27	export interface Turn<S, R> { readonly state: S; readonly out: readonly string[]; readonly result?: R }
28	export interface Screen<S, R> { readonly start: Turn<S, R>; readonly next: (state: S, line: string) => Turn<S, R> }
29	export const runScreen = async <S, R>(screen: Screen<S, R>, io: LineIO, prompt?: string): Promise<R | undefined> => {
30	  let turn = screen.start;
31	  for (const line of turn.out) io.write(line);
32	  for (;;) {
33	    const line = await io.ask(prompt);
34	    if (line === undefined) return undefined;
35	    turn = screen.next(turn.state, line);
36	    if (turn.result !== undefined) return turn.result;
37	    for (const line of turn.out) io.write(line);
38	  }
