140	    state: { phase: 'main', index: 0, goals: input.goals.goals, nonGoals: input.goals.nonGoals, walkedGoals: [], walkedNonGoals: [] },
141	    out: mainLines(input, { phase: 'main', index: 0, goals: input.goals.goals, nonGoals: input.goals.nonGoals, walkedGoals: [], walkedNonGoals: [] }),
142	  },
143	  next: (state, line) => {
