158	export const applyResolve = async (result: ResolveResult, record: PausePayload, originalGoals: GoalsDocStub, cli: readonly string[]): Promise<void> => {
159	  if (result.kind !== 'accept') return;
160	  const file = record.inputs.goals;
161	  const irSetResult = await irSet({ cli, kind: 'goals', file, path: '$.goals', value: result.goals });
162	  assertOk(irSetResult);
163	  const nonGoalsChanged = JSON.stringify(result.nonGoals) !== JSON.stringify(originalGoals.nonGoals);
164	  if (nonGoalsChanged) {
165	    const nonGoalsResult = await irSet({ cli, kind: 'goals', file, path: '$.nonGoals', value: result.nonGoals });
166	    assertOk(nonGoalsResult);
167	  }
168	  const validateResult = await irValidate({ cli, kind: 'goals', file });
169	  assertOk(validateResult);
170	  cpSync(record.inputs.template, record.outputs[0]);
171	};
